<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My reservations | CoworkSpace</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="navbar"><div class="container nav-content"><a class="logo" href="index.php">Cowork<span>Space</span></a><nav class="nav-links"><a href="spaces.php">Availability</a><a class="active" href="my-reservations.php">My reservations</a><a href="logout.php">Log out</a></nav></div></header><main class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">YOUR BOOKINGS</span><h1>My reservations</h1></div><a class="btn" href="spaces.php">Find a time slot</a></div><?php if(isset($_GET["created"])):?><div class="alert success">Reservation submitted and pending review.</div><?php endif;?><?php if(isset($_GET["cancelled"])):?><div class="alert success">Reservation cancelled.</div><?php endif;?><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(!$rows):?><div class="empty-state"><h2>No reservations yet</h2><p>Browse slots to make your first reservation.</p></div><?php else:?><div class="table-wrapper"><table><thead><tr><th>Space</th><th>Date</th><th>Time</th><th>Note</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):$can=in_array($r["status"],["pending","confirmed"],true)&&($r["booking_date"]>date("Y-m-d")||($r["booking_date"]===date("Y-m-d")&&$r["start_time"]>date("H:i:s")));?><tr><td><?=htmlspecialchars($r["space_name"])?></td><td><?=htmlspecialchars($r["booking_date"])?></td><td><?=htmlspecialchars(substr($r["start_time"],0,5))?> - <?=htmlspecialchars(substr($r["end_time"],0,5))?></td><td><?=htmlspecialchars($r["note"]??"")?></td><td><span class="badge badge-<?=htmlspecialchars($r["status"])?>"><?=htmlspecialchars(ucfirst($r["status"]))?></span></td><td><?php if($can):?><form method="POST"><input type="hidden" name="reservation_id" value="<?=(int)$r["id"]?>"><button class="btn btn-danger btn-small">Cancel</button></form><?php else:?><span class="muted">-</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></main><footer class="footer"><div class="container">CoworkSpace</div></footer></body></html>
